// Get all fetched data
const tradeTickets = $('Jira: Fetch TRADE Completed').all().map(i => i.json);
const infraTickets = $('Jira: Fetch INFRA Completed').all().map(i => i.json);
const learnTickets = $('Jira: Fetch LEARN Completed').all().map(i => i.json);
const mgmtTickets = $('Jira: Fetch MGMT Completed').all().map(i => i.json);
const trades = $('HTTP: Fetch Week Trades').first()?.json?.trades || [];
const grades = $('HTTP: Fetch Trade Grades').first()?.json?.grades || [];
const incidents = $('Jira: Fetch Incidents').all().map(i => i.json);
const agentActivity = $('HTTP: Fetch Agent Activity').first()?.json || {};
const approvals = $('HTTP: Fetch CEO Approvals').first()?.json?.approvals || [];
const uptimeData = $('HTTP: Fetch System Uptime').first()?.json || {};

// Calculate story points helper
const getPoints = (issue) => {
  return issue.fields?.customfield_storypoints || 
         issue.fields?.customfield_10016 || 1;
};

// Sprint Velocity
const allCompleted = [...tradeTickets, ...infraTickets, ...learnTickets, ...mgmtTickets];
const totalVelocity = allCompleted.reduce((sum, i) => sum + getPoints(i), 0);
const velocityByProject = {
  TRADE: tradeTickets.reduce((sum, i) => sum + getPoints(i), 0),
  INFRA: infraTickets.reduce((sum, i) => sum + getPoints(i), 0),
  LEARN: learnTickets.reduce((sum, i) => sum + getPoints(i), 0),
  MGMT: mgmtTickets.reduce((sum, i) => sum + getPoints(i), 0)
};

// Trading P&L
const totalPnL = trades.reduce((sum, t) => sum + (parseFloat(t.pnl) || 0), 0);
const winningTrades = trades.filter(t => parseFloat(t.pnl) > 0);
const losingTrades = trades.filter(t => parseFloat(t.pnl) < 0);
const winRate = trades.length > 0 ? (winningTrades.length / trades.length * 100) : 0;
const avgWin = winningTrades.length > 0 
  ? winningTrades.reduce((s, t) => s + parseFloat(t.pnl), 0) / winningTrades.length 
  : 0;
const avgLoss = losingTrades.length > 0 
  ? Math.abs(losingTrades.reduce((s, t) => s + parseFloat(t.pnl), 0) / losingTrades.length)
  : 0;
const profitFactor = avgLoss > 0 ? avgWin / avgLoss : avgWin > 0 ? Infinity : 0;

// Grade distribution
const gradeDistribution = {};
grades.forEach(g => {
  const grade = g.grade || 'Ungraded';
  gradeDistribution[grade] = (gradeDistribution[grade] || 0) + 1;
});
const avgGradeScore = grades.length > 0 
  ? grades.reduce((s, g) => s + (g.score || 60), 0) / grades.length 
  : 0;

// Incidents analysis
const resolvedIncidents = incidents.filter(i => i.fields?.status?.name === 'Done');
const openIncidents = incidents.filter(i => i.fields?.status?.name !== 'Done');
const criticalIncidents = incidents.filter(i => 
  i.fields?.priority?.name === 'Highest' || i.fields?.priority?.name === 'High'
);

// Agent efficiency
const agents = agentActivity.agents || [];
const totalTasks = agents.reduce((s, a) => s + (a.tasksCompleted || 0), 0);
const totalErrors = agents.reduce((s, a) => s + (a.errors || 0), 0);
const agentEfficiency = totalTasks > 0 ? ((totalTasks - totalErrors) / totalTasks * 100) : 100;

// System uptime
const uptimePercent = uptimeData.uptimePercent || 99.9;
const downtimeMinutes = uptimeData.downtimeMinutes || 0;

// CEO Approvals analysis
const approved = approvals.filter(a => a.decision === 'approved');
const rejected = approvals.filter(a => a.decision === 'rejected');
const pending = approvals.filter(a => a.decision === 'pending');
const approvalRate = approvals.length > 0 
  ? (approved.length / approvals.length * 100) 
  : 100;

// Identify highlights and lowlights
const highlights = [];
const lowlights = [];

if (totalPnL > 0) highlights.push(`Profitable week: +$${totalPnL.toFixed(2)}`);
else if (totalPnL < 0) lowlights.push(`Week loss: -$${Math.abs(totalPnL).toFixed(2)}`);

if (totalVelocity >= 15) highlights.push(`Strong velocity: ${totalVelocity} story points`);
else if (totalVelocity < 8) lowlights.push(`Low velocity: ${totalVelocity} story points`);

if (winRate >= 60) highlights.push(`High win rate: ${winRate.toFixed(1)}%`);
else if (winRate < 40) lowlights.push(`Low win rate: ${winRate.toFixed(1)}%`);

if (criticalIncidents.length === 0) highlights.push('No critical incidents this week');
else lowlights.push(`${criticalIncidents.length} critical incident(s)`);

if (uptimePercent >= 99.5) highlights.push(`Excellent uptime: ${uptimePercent.toFixed(2)}%`);
else if (uptimePercent < 95) lowlights.push(`Uptime issues: ${uptimePercent.toFixed(2)}%`);

if (agentEfficiency >= 95) highlights.push(`High agent efficiency: ${agentEfficiency.toFixed(1)}%`);
else if (agentEfficiency < 80) lowlights.push(`Agent issues: ${agentEfficiency.toFixed(1)}% efficiency`);

// Week dates
const weekStart = new Date();
weekStart.setDate(weekStart.getDate() - 7);
const weekEnd = new Date();

return {
  json: {
    weekRange: `${weekStart.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} - ${weekEnd.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}`,

    velocity: {
      total: totalVelocity,
      ticketCount: allCompleted.length,
      byProject: velocityByProject
    },

    trading: {
      totalPnL: totalPnL.toFixed(2),
      tradeCount: trades.length,
      winRate: winRate.toFixed(1),
      avgWin: avgWin.toFixed(2),
      avgLoss: avgLoss.toFixed(2),
      profitFactor: profitFactor === Infinity ? 'N/A' : profitFactor.toFixed(2),
      avgGradeScore: avgGradeScore.toFixed(0),
      gradeDistribution
    },

    incidents: {
      total: incidents.length,
      resolved: resolvedIncidents.length,
      open: openIncidents.length,
      critical: criticalIncidents.length,
      details: incidents.slice(0, 5).map(i => ({
        key: i.key,
        summary: i.fields?.summary?.substring(0, 60),
        status: i.fields?.status?.name,
        priority: i.fields?.priority?.name
      }))
    },

    agents: {
      totalTasks,
      totalErrors,
      efficiency: agentEfficiency.toFixed(1),
      details: agents.map(a => ({
        name: a.name,
        tasks: a.tasksCompleted || 0,
        errors: a.errors || 0
      }))
    },

    system: {
      uptimePercent: uptimePercent.toFixed(2),
      downtimeMinutes
    },

    approvals: {
      total: approvals.length,
      approved: approved.length,
      rejected: rejected.length,
      pending: pending.length,
      approvalRate: approvalRate.toFixed(1)
    },

    highlights,
    lowlights,

    completedTickets: allCompleted.slice(0, 15).map(t => ({
      key: t.key,
      summary: t.fields?.summary?.substring(0, 50),
      project: t.fields?.project?.key,
      points: getPoints(t)
    })),

    timestamp: new Date().toISOString()
  }
};

const metrics = $input.first().json;

const prompt = `You are the weekly retrospective facilitator for SwjshAK autonomous trading system.

Generate a comprehensive yet concise weekly retrospective based on this data:

## WEEK: ${metrics.weekRange}

### SPRINT VELOCITY
- Total Story Points: ${metrics.velocity.total}
- Tickets Completed: ${metrics.velocity.ticketCount}
- By Project: TRADE=${metrics.velocity.byProject.TRADE}, INFRA=${metrics.velocity.byProject.INFRA}, LEARN=${metrics.velocity.byProject.LEARN}, MGMT=${metrics.velocity.byProject.MGMT}

### TRADING PERFORMANCE
- Total P&L: $${metrics.trading.totalPnL}
- Win Rate: ${metrics.trading.winRate}%
- Trade Count: ${metrics.trading.tradeCount}
- Avg Win: $${metrics.trading.avgWin} | Avg Loss: $${metrics.trading.avgLoss}
- Profit Factor: ${metrics.trading.profitFactor}
- Average Trade Grade: ${metrics.trading.avgGradeScore}/100
- Grade Distribution: ${JSON.stringify(metrics.trading.gradeDistribution)}

### SYSTEM RELIABILITY
- Uptime: ${metrics.system.uptimePercent}%
- Downtime: ${metrics.system.downtimeMinutes} minutes

### INCIDENTS
- Total: ${metrics.incidents.total}
- Resolved: ${metrics.incidents.resolved}
- Open: ${metrics.incidents.open}
- Critical: ${metrics.incidents.critical}

### AGENT EFFICIENCY
- Tasks Completed: ${metrics.agents.totalTasks}
- Errors: ${metrics.agents.totalErrors}
- Efficiency Rate: ${metrics.agents.efficiency}%

### CEO APPROVALS
- Total Decisions: ${metrics.approvals.total}
- Approved: ${metrics.approvals.approved}
- Rejected: ${metrics.approvals.rejected}
- Pending: ${metrics.approvals.pending}
- Approval Rate: ${metrics.approvals.approvalRate}%

### KEY HIGHLIGHTS
${metrics.highlights.map(h => '- ' + h).join('\n')}

### AREAS OF CONCERN
${metrics.lowlights.map(l => '- ' + l).join('\n')}

### COMPLETED TICKETS (Sample)
${metrics.completedTickets.map(t => '- [' + t.key + '] ' + t.summary + ' (' + t.points + ' pts)').join('\n')}

---

Provide a retrospective in this format:

## WHAT WENT WELL
(3-5 specific wins with context - be celebratory)

## WHAT WENT WRONG
(2-4 honest assessments - be constructive, not harsh)

## WHAT TO IMPROVE
(3-5 actionable items for next week - specific and measurable)

## NEXT WEEK FOCUS AREAS
(2-3 priority areas based on the data)

## TEAM KUDOS
(Call out any standout agent or system performance)

Be honest, data-driven, and actionable. Max 500 words. Use emojis sparingly for emphasis.`;

return {
  json: {
    prompt,
    metrics,
    weekRange: metrics.weekRange
  }
};

const response = $json;
const prevData = $('Code: Build Retrospective Prompt').first().json;

// Extract retrospective text
let retroText = '';
if (response?.content?.[0]?.text) {
  retroText = response.content[0].text;
} else {
  retroText = 'Failed to generate retrospective. Please review manually.';
}

// Parse sections for structured storage
const sections = {
  wentWell: '',
  wentWrong: '',
  toImprove: '',
  focusAreas: '',
  kudos: ''
};

const wellMatch = retroText.match(/## WHAT WENT WELL([\s\S]*?)(?=## WHAT WENT WRONG|$)/i);
if (wellMatch) sections.wentWell = wellMatch[1].trim();

const wrongMatch = retroText.match(/## WHAT WENT WRONG([\s\S]*?)(?=## WHAT TO IMPROVE|$)/i);
if (wrongMatch) sections.wentWrong = wrongMatch[1].trim();

const improveMatch = retroText.match(/## WHAT TO IMPROVE([\s\S]*?)(?=## NEXT WEEK|$)/i);
if (improveMatch) sections.toImprove = improveMatch[1].trim();

const focusMatch = retroText.match(/## NEXT WEEK FOCUS([\s\S]*?)(?=## TEAM KUDOS|$)/i);
if (focusMatch) sections.focusAreas = focusMatch[1].trim();

const kudosMatch = retroText.match(/## TEAM KUDOS([\s\S]*?)$/i);
if (kudosMatch) sections.kudos = kudosMatch[1].trim();

return {
  json: {
    retroText,
    sections,
    metrics: prevData.metrics,
    weekRange: prevData.weekRange
  }
};

const data = $json;
const metrics = data.metrics;

// Determine color based on overall performance
let embedColor = 3066993; // Green
const pnl = parseFloat(metrics.trading.totalPnL);
const velocity = metrics.velocity.total;

if (pnl < -500 || metrics.incidents.critical > 2) {
  embedColor = 15158332; // Red
} else if (pnl < 0 || metrics.incidents.critical > 0 || velocity < 8) {
  embedColor = 16776960; // Yellow
}

// Build embed
const embed = {
  title: `:clipboard: Weekly Retrospective - ${data.weekRange}`,
  description: data.retroText.substring(0, 4000),
  color: embedColor,
  fields: [
    {
      name: ':chart_with_upwards_trend: Velocity',
      value: `${metrics.velocity.total} points (${metrics.velocity.ticketCount} tickets)`,
      inline: true
    },
    {
      name: ':dollar: P&L',
      value: `$${metrics.trading.totalPnL}`,
      inline: true
    },
    {
      name: ':dart: Win Rate',
      value: `${metrics.trading.winRate}%`,
      inline: true
    },
    {
      name: ':shield: Uptime',
      value: `${metrics.system.uptimePercent}%`,
      inline: true
    },
    {
      name: ':warning: Incidents',
      value: `${metrics.incidents.total} (${metrics.incidents.critical} critical)`,
      inline: true
    },
    {
      name: ':robot: Agent Efficiency',
      value: `${metrics.agents.efficiency}%`,
      inline: true
    }
  ],
  footer: {
    text: 'SwjshAK Weekly Retrospective | WF-MGMT-01'
  },
  timestamp: new Date().toISOString()
};

return {
  json: {
    embed,
    retroText: data.retroText,
    sections: data.sections,
    metrics,
    weekRange: data.weekRange,
    channelId: process.env.DISCORD_CEO_CHANNEL_ID || 'ceo-briefing'
  }
};

